def mc(doc,page,prompt,a,b,c,e,why,level='understand'):
 add(doc,page,'single_choice',prompt,'a',why,[a,b,c,e]);q=qs[-1];q['id']=f'{doc}-x{sum(x["topic"]==doc for x in qs):02}';q['author_id']='question-engineer-b';q['cognitive_level']=level
d='p2-t4-d01'
mc(d,9,'Tập dữ liệu nào nên dùng để chọn thời điểm dừng và siêu tham số?','Validation set','Test set dùng lại sau mỗi lựa chọn','Training set thay mọi đánh giá tổng quát hóa','Gộp test và train trước khi chọn siêu tham số','Validation phục vụ lựa chọn mô hình; test dành báo cáo cuối để tránh tối ưu theo tập kiểm tra.')
mc(d,12,'Lớp fully connected có 3 đầu vào và 4 nơ-ron, mỗi nơ-ron có một bias. Lớp có bao nhiêu tham số?','16','12','7','15','Mỗi nơ-ron có 3 weights và 1 bias; tổng là 4×(3+1)=16.','apply')
mc(d,13,'Xếp nhiều lớp affine mà không có activation phi tuyến làm giới hạn biểu diễn thế nào?','Toàn mạng vẫn gộp được thành một phép affine','Độ sâu tự sinh phi tuyến dù từng lớp chỉ affine','Bias giữa các lớp tạo mọi hàm phi tuyến cần thiết','Chỉ cần nhiều ma trận thì mạng luôn biểu diễn được XOR','Hợp của các phép affine vẫn affine; activation phi tuyến ngăn việc gộp này.')
mc(d,17,'Một nơ-ron sigmoid nằm ở vùng đầu ra gần 0 hoặc 1 thường học chậm vì sao?','Đạo hàm sigmoid rất nhỏ ở vùng bão hòa','Đạo hàm sigmoid luôn lớn nhất ở hai đầu','Bias tự động bị đóng băng khi xác suất gần 1','Backprop bỏ qua mọi nơ-ron có đầu ra khác 0.5','Gradient nhân với đạo hàm activation; vùng phẳng truyền gradient rất yếu.')
mc(d,18,'Định lý xấp xỉ phổ quát có bảo đảm gradient descent tìm được mạng phù hợp không?','Không; sự tồn tại của mạng không bảo đảm quá trình tối ưu tìm được nó','Có; chỉ cần một lớp ẩn thì mọi lần huấn luyện hội tụ','Có; định lý cho sẵn số nơ-ron tối thiểu cho mọi dataset','Không; vì mọi hàm liên tục đều không thể được xấp xỉ bằng mạng','Định lý nói về năng lực biểu diễn trên miền thích hợp, không bảo đảm độ rộng thực tế hoặc tối ưu thành công.')
mc(d,27,'Đạo hàm riêng của loss theo một weight được hiểu với điều kiện nào?','Giữ các weights còn lại cố định','Thay đồng thời mọi weight với cùng một lượng','Chỉ thay nhãn và giữ weight cố định','Tính độ chính xác cuối cùng thay đổi sau cả epoch','Đạo hàm riêng đo tác động cục bộ của một tham số khi các tham số khác cố định.')
mc(d,33,'Giảm bước h của finite difference xuống cực nhỏ luôn cải thiện độ chính xác không?','Không; phép trừ hai giá trị gần nhau có thể khuếch đại sai số làm tròn','Có; h càng gần 0 thì số học hữu hạn luôn chính xác hơn','Có; rounding error chỉ xuất hiện khi h quá lớn','Không; vì finite difference chỉ hợp lệ khi h bằng 1','Có đánh đổi truncation error khi h lớn và rounding error khi h quá nhỏ.')
mc(d,36,'Backprop hiệu quả hơn tính từng đạo hàm bằng finite difference chủ yếu nhờ điều gì?','Tái sử dụng các thừa số gradient chung từ đầu ra về đầu vào','Thử perturb riêng mọi weight bằng hai forward passes','Bỏ qua gradient của các lớp ẩn','Cập nhật weights mà không cần tính loss','Reverse-mode chain rule dùng lại trung gian và thừa số chung thay tính lại cho từng tham số.')
mc(d,44,'Gradient checkpointing giảm bộ nhớ bằng cách đánh đổi gì?','Tính lại một phần activations nên tốn thêm thời gian','Bỏ gradient của mọi layer đã checkpoint','Lưu toàn bộ activations ở độ chính xác cao hơn','Thay optimizer bằng inference-only nên không cập nhật được','Checkpointing giữ ít trung gian hơn và tái tính trong backward, đổi compute lấy memory.')
mc(d,46,'Autograd trả gradient hợp lệ có chứng minh loss phù hợp với bài toán không?','Không; nó vi phân biểu thức đã viết, kể cả mục tiêu được chọn sai','Có; autograd tự đổi loss theo nhãn nghiệp vụ','Có; gradient khác 0 chứng minh metric sẽ tăng','Không; vì autograd không thể tính gradient cho neural network','Đồ thị tính toán cho đạo hàm của loss được cung cấp; lựa chọn mục tiêu vẫn cần thiết kế và kiểm tra.')
mc(d,51,'Một batch hồi quy có nhãn ngoại lai với sai số rất lớn. Vì sao MSE có thể bị mẫu đó chi phối?','Sai số được bình phương nên tăng gấp đôi làm penalty tăng gấp bốn','MSE chặn mọi gradient lớn ở mức cố định','MSE chỉ tính các mẫu gần trung bình nhãn','MSE bỏ mọi mẫu có sai số lớn hơn 1','Bình phương phạt outlier mạnh; gradient cũng tăng theo độ lệch dự đoán.')
mc(d,52,'BCEWithLogitsLoss nhận logits trực tiếp mang lợi ích số học nào?','Tính dạng ổn định tránh log của xác suất làm tròn sát 0 và tràn mũ','Bắt buộc người dùng sigmoid hai lần để tăng ổn định','Loại bỏ hoàn toàn ảnh hưởng của nhãn sai','Biến bài toán nhị phân thành hồi quy bình phương','Dạng loss từ logits dùng log-sum-exp ổn định thay sigmoid rồi log ngây thơ.')
mc(d,58,'Smooth-L1 kết hợp hành vi nào để hồi quy hộp ổn định?','Trơn gần sai số 0 và gradient bị chặn khi sai số lớn','Bình phương mọi sai số với gradient tăng không giới hạn','Gradient bằng 0 cho mọi hộp không giao nhau','Giữ gradient hằng số và không trơn tại 0 như L1 thuần','Smooth-L1 dùng vùng quadratic gần 0 và tuyến tính ở xa để tránh outlier gây bước quá lớn.')
mc(d,69,'Mini-batch tăng kích thước gấp bốn làm độ nhiễu gradient ước lượng thay đổi xấp xỉ thế nào?','Giảm còn một nửa','Giảm còn một phần tư','Giữ nguyên vì batch size không ảnh hưởng','Tăng gấp đôi','Độ nhiễu giảm theo 1/sqrt(B), nên B×4 cho độ nhiễu×1/2.','apply')
mc(d,71,'Momentum giúp xử lý gradient dao động qua lại như thế nào?','Tích lũy hướng ổn định và triệt bớt các hướng đổi dấu','Bỏ toàn bộ gradient cũ ở mỗi bước','Chỉ giữ bình phương gradient nên không có thông tin hướng','Luôn tăng learning rate bất kể lịch sử hướng đi','Momentum dùng tổng gradient có suy giảm theo thời gian, giữ quán tính hướng hữu ích.')
mc(d,78,'Early stopping nên giữ bộ weights nào để giảm overfitting?','Weights tại thời điểm validation loss thấp nhất','Weights ở epoch cuối dù validation loss đã tăng','Weights có training loss nhỏ nhất bất kể validation','Trung bình nhãn thay mọi weights khi loss tăng','Early stopping dựa cải thiện validation, không mặc định chọn trạng thái cuối cùng.')
d='p2-t4-d02'
mc(d,9,'Giữ nguyên kernel và số kênh nhưng tăng độ phân giải ảnh. Đại lượng nào của convolution tăng theo diện tích output?','Chi phí tính toán, trong khi số weights không đổi','Số weights tăng theo mọi vị trí output','Số bias tăng theo từng pixel đầu vào','Cả compute và parameters đều giữ nguyên','Weight sharing làm parameters độc lập kích thước ảnh, nhưng kernel phải được áp dụng tại nhiều vị trí hơn.')
mc(d,9,'Convolution 1×1 chủ yếu trộn thông tin theo hướng nào?','Giữa các kênh tại cùng vị trí','Giữa các pixel xa nhau mà bỏ kênh','Chỉ theo hàng ngang bằng cửa sổ rộng','Chỉ lấy cực đại trong vùng không gian','1×1 là phép tuyến tính trên channel vector tại mỗi pixel, không tự trộn vị trí lân cận.')
mc(d,12,'Translation equivariance của convolution nghĩa là gì?','Vật dịch vị trí thì feature map dịch tương ứng','Vật dịch thì mọi feature map phải giữ nguyên tại từng pixel','Convolution luôn bỏ toàn bộ thông tin vị trí','Pooling luôn giữ tọa độ chính xác của cực đại','Equivariance giữ quan hệ biến đổi đầu vào/đầu ra; invariance giữ nhãn không đổi và thường chỉ gần đúng nhờ pooling.')
mc(d,14,'Hai convolution 3×3 stride1 so với một convolution 5×5 với cùng số kênh có lợi thế nào?','Cùng receptive field 5×5, ít weights hơn và thêm phi tuyến','Cùng số weights nhưng receptive field nhỏ hơn','Receptive field thành 6×6 vì cộng hai kernel sizes','Không có thêm phi tuyến dù activation đặt giữa hai lớp','Stack small kernels tiết kiệm tham số cho cùng vùng nhìn và tăng bước phi tuyến ở giữa.')
mc(d,17,'CNN phát hiện dùng mini-batch rất nhỏ cần normalization ít phụ thuộc batch. Lựa chọn nào phù hợp?','GroupNorm tính theo nhóm kênh của từng mẫu','BatchNorm bắt buộc dùng thống kê của toàn tập ở mỗi train step','Chỉ tăng momentum optimizer để thay normalization','Dùng cùng một mean cho mọi kênh và mọi mẫu bất kể dữ liệu','GroupNorm độc lập batch size, phù hợp lô nhỏ hơn BatchNorm dựa thống kê lô.')
mc(d,21,'RNN dùng được chuỗi dài khác nhau mà số tham số không tăng theo số bước nhờ điều gì?','Dùng chung các ma trận weights ở mọi bước thời gian','Tạo bộ weights mới cho mỗi frame nhận được','Lưu mỗi input thành một tham số trainable mới','Bỏ hidden state khi chiều dài thay đổi','Recurrence áp dụng cùng phép chuyển trạng thái ở từng bước; độ dài tăng compute chứ không thêm bộ weights.')
mc(d,24,'Gradient clipping có thể tự khôi phục gradient đã rất nhỏ do vanishing không?','Không; nó chỉ thu nhỏ gradient quá lớn, không khuếch đại gradient nhỏ','Có; mọi vector được chuẩn hóa thành cùng norm lớn','Có; clipping thay mọi activation bằng identity','Không; vì clipping chỉ dùng khi inference','Norm clipping giới hạn bước lớn; phụ thuộc dài cần kiến trúc có đường truyền thông tin phù hợp.')
mc(d,25,'Trong LSTM, cổng quên điều khiển phần thông tin nào?','Phần cell state cũ được giữ lại','Chỉ phần cell state được đưa ra hidden output','Chỉ nội dung ứng viên mới được ghi vào cell','Số timestep được tạo thêm trong chuỗi','Forget gate nhân với cell state trước; input gate điều khiển ghi mới và output gate điều khiển đọc ra.')
mc(d,28,'RNN có hạn chế song song hóa theo thời gian vì sao?','Bước hiện tại cần hidden state của bước trước','Mỗi timestep bắt buộc dùng model weights khác nhau','RNN không thể dùng matrix multiplication trên GPU','Mọi sequence phải có độ dài cố định bằng hidden dimension','Phụ thuộc tuần tự h_t vào h_(t-1) tạo chuỗi tính toán theo thời gian.')
mc(d,30,'Trong attention, weights so khớp query–key được dùng để tổng hợp đại lượng nào?','Các value vectors','Các token position ID thay mọi nội dung','Chỉ query vector lặp lại nhiều lần','Chỉ key norms mà bỏ value vectors','Query/key xác định mức liên quan; weighted sum của values là nội dung trả về.')
mc(d,33,'Self-attention không có positional information thiếu loại thông tin nào cho chuỗi?','Thứ tự hoặc vị trí của token','Khả năng so khớp query với key','Khả năng tổng hợp value theo weights','Mọi khả năng dùng gradient để train','Attention trên tập là permutation equivariant; positional encoding đưa cấu trúc vị trí vào token.')
mc(d,35,'Cross-attention khác self-attention ở nguồn Q/K/V ra sao?','Q từ một tập, K và V từ tập khác','Q/K/V đều bắt buộc từ một token duy nhất','Chỉ đổi số head còn nguồn Q/K/V luôn giống self-attention','K lấy từ output tương lai chưa được tính, V không cần','Cross-attention cho truy vấn đọc nội dung từ tập đặc trưng khác, như object queries đọc ảnh.')
mc(d,44,'Swin giảm chi phí attention trên ảnh lớn bằng cơ chế không gian nào?','Attention trong cửa sổ và dịch cửa sổ giữa các lớp','Global attention trên mọi pixel ở mọi lớp','Bỏ mọi kết nối giữa các token trong cùng cửa sổ','Giữ một cửa sổ duy nhất phủ nguyên ảnh ở mọi độ phân giải','Window attention giới hạn số cặp tương tác; shifted windows cho trao đổi qua ranh giới cửa sổ.')
mc(d,57,'Lật ngang ảnh chứa nhãn làn trái/phải cần được xử lý thận trọng vì sao?','Biến đổi có thể đổi nghĩa nhãn hướng nên không còn label-preserving','Mọi augmentation hình học luôn giữ mọi nhãn nguyên vẹn','Lật ngang chỉ đổi màu nên không ảnh hưởng hình học','Chỉ classification mới cần kiểm nhãn, robotics không cần','Augmentation là giả định về bất biến; nhãn mang hướng phải được biến đổi phù hợp hoặc tránh phép lật.')
mc(d,58,'Tinh chỉnh pretrained backbone cùng head mới khởi tạo thường đặt learning rate thế nào?','Backbone thấp hơn head để tránh phá đặc trưng đã học','Backbone luôn cao hơn head vì đã hội tụ trước','Cả hai luôn bằng 0 để bảo toàn pretraining','Chỉ head có weight decay thì backbone không cần learning rate','Head mới cần học nhanh hơn; backbone dùng bước nhỏ để giữ tri thức hữu ích trong chuyển giao.')
mc(d,70,'TTA cho detection phải làm gì trước khi gộp các hộp từ ảnh lật hoặc đổi cỡ?','Đưa tọa độ dự đoán về hệ quy chiếu ảnh gốc','Gộp trực tiếp mọi tọa độ của các view khác nhau','Chỉ lấy trung bình class logits và bỏ tọa độ','Coi hộp từ view lật là cùng tọa độ với ảnh gốc','Dự đoán không gian phải inverse-transform về cùng frame trước fusion; TTA cần nhiều lượt inference.')
